// @ts-check
__card__({
  id: 'browse',
  packId: 'ui.card.v1',
  title: 'Browse Inventory',
  icon: '📋',
});

__doc__({
  name: 'browse',
  summary: 'Inventory listing card with quick-open actions for individual SKUs.',
  tags: ['inventory', 'table', 'browse'],
  related: ['ui.table', 'ui.column', 'itemDetail'],
});

doc`
---
symbol: browse
---
The browse card demonstrates a table-heavy ui.card.v1 screen. It renders all inventory rows and a
secondary quick-open action column for jumping into item detail.
`;

defineRuntimeSurface(
  'browse',
  ({ ui }) => ({
    render({ state }) {
      const items = selectItems(state);
      const quickOpen = items.slice(0, 10).map((item) => {
        const row = asRecord(item);
        const sku = String(row.sku || '');
        return ui.button('Open ' + sku, { onClick: { handler: 'open', args: { sku } } });
      });

      return ui.panel([
        ui.text('Browse Inventory (' + items.length + ' items)'),
        ui.table(itemRows(items), { headers: ['SKU', 'Name', 'Category', 'Price', 'Qty'] }),
        ui.text('Quick open:'),
        ui.column(quickOpen),
        ui.row([
          ui.button('➕ New Item', { onClick: { handler: 'go', args: { surfaceId: 'newItem' } } }),
          ui.button('🏠 Home', { onClick: { handler: 'go', args: { surfaceId: 'home' } } }),
        ]),
      ]);
    },
    handlers: {
      go({ dispatch }, args) {
        dispatch({ type: 'nav.go', payload: { surfaceId: String(asRecord(args).surfaceId || 'home') } });
      },
      open({ dispatch }, args) {
        dispatch({
          type: 'nav.go',
          payload: {
            surfaceId: 'itemDetail',
            param: String(asRecord(args).sku || ''),
          },
        });
      },
    },
  }),
  'ui.card.v1',
);

// @ts-check
__card__({
  id: 'home',
  packId: 'ui.card.v1',
  title: 'Home',
  icon: '🏠',
});

__doc__({
  name: 'home',
  summary: 'Inventory landing card with quick links into the main inventory workflows.',
  tags: ['inventory', 'demo', 'navigation'],
  related: ['ui.panel', 'ui.button'],
});

doc`
---
symbol: home
---
The home card is the entry point for the inventory stack. It demonstrates a simple navigation card
built entirely from text and button primitives.
`;

defineRuntimeSurface(
  'home',
  ({ ui }) => ({
    render() {
      return ui.panel([
        ui.text('Welcome to Shop Inventory'),
        ui.text('Plugin DSL runtime'),
        ui.button('📋 Browse Items', { onClick: { handler: 'go', args: { surfaceId: 'browse' } } }),
        ui.button('⚠️ Low Stock', { onClick: { handler: 'go', args: { surfaceId: 'lowStock' } } }),
        ui.button('💰 Sales Today', { onClick: { handler: 'go', args: { surfaceId: 'salesToday' } } }),
        ui.button('📊 Inventory Report', { onClick: { handler: 'go', args: { surfaceId: 'report' } } }),
        ui.button('📦 Receive Shipment', { onClick: { handler: 'go', args: { surfaceId: 'receive' } } }),
        ui.button('➕ New Item', { onClick: { handler: 'go', args: { surfaceId: 'newItem' } } }),
        ui.button('🏷 Price Checker', { onClick: { handler: 'go', args: { surfaceId: 'priceCheck' } } }),
      ]);
    },
    handlers: {
      go({ dispatch }, args) {
        dispatch({ type: 'nav.go', payload: { surfaceId: String(asRecord(args).surfaceId || 'home') } });
      },
    },
  }),
  'ui.card.v1',
);

// @ts-check
__card__({
  id: 'itemDetail',
  packId: 'ui.card.v1',
  title: 'Item Detail',
  icon: '📦',
});

__doc__({
  name: 'itemDetail',
  summary: 'Editable item detail card with quantity deltas and draft-backed form state.',
  tags: ['inventory', 'detail', 'forms'],
  related: ['ui.input', 'ui.row', 'browse'],
});

doc`
---
symbol: itemDetail
---
The itemDetail card is the main editable form example in the inventory stack. It demonstrates
draft-backed field editing, optimistic quantity delta actions, and destructive item removal.
`;

defineRuntimeSurface(
  'itemDetail',
  ({ ui }) => ({
    render({ state }) {
      const sku = navParam(state);
      const record = findItem(state, sku);
      if (!record) {
        return ui.panel([
          ui.text('Item not found: ' + String(sku || '(none)')),
          ui.button('← Back', { onClick: { handler: 'back' } }),
        ]);
      }

      const edits = asRecord(draft(state).edits);
      const current = { ...asRecord(record), ...edits };

      return ui.panel([
        ui.text('Item Detail: ' + String(current.sku || '')),
        ui.row([
          ui.text('Name:'),
          ui.input(String(current.name || ''), { onChange: { handler: 'change', args: { field: 'name' } } }),
        ]),
        ui.row([
          ui.text('Category:'),
          ui.input(String(current.category || ''), { onChange: { handler: 'change', args: { field: 'category' } } }),
        ]),
        ui.row([
          ui.text('Price:'),
          ui.input(String(toNumber(current.price, 0)), { onChange: { handler: 'change', args: { field: 'price' } } }),
        ]),
        ui.row([
          ui.text('Cost:'),
          ui.input(String(toNumber(current.cost, 0)), { onChange: { handler: 'change', args: { field: 'cost' } } }),
        ]),
        ui.row([
          ui.text('Qty:'),
          ui.input(String(toNumber(current.qty, 0)), { onChange: { handler: 'change', args: { field: 'qty' } } }),
        ]),
        ui.row([
          ui.text('Tags:'),
          ui.input(asArray(current.tags).join(', '), { onChange: { handler: 'change', args: { field: 'tags' } } }),
        ]),
        ui.row([
          ui.button('🛒 Sell 1', { onClick: { handler: 'delta', args: { delta: -1 } } }),
          ui.button('🛒 Sell 5', { onClick: { handler: 'delta', args: { delta: -5 } } }),
          ui.button('📦 Receive +5', { onClick: { handler: 'delta', args: { delta: 5 } } }),
          ui.button('📦 Receive +10', { onClick: { handler: 'delta', args: { delta: 10 } } }),
        ]),
        ui.row([
          ui.button('✏️ Save Changes', { onClick: { handler: 'save' } }),
          ui.button('🗑 Delete', { onClick: { handler: 'remove' } }),
          ui.button('← Back', { onClick: { handler: 'back' } }),
        ]),
      ]);
    },
    handlers: {
      back({ dispatch }) {
        dispatch({ type: 'nav.back' });
      },
      change({ dispatch }, args) {
        const field = String(asRecord(args).field || '');
        const value = asRecord(args).value;
        if (!field) return;

        let nextValue = value;
        if (field === 'qty' || field === 'price' || field === 'cost') {
          nextValue = toNumber(value, 0);
        }
        if (field === 'tags') {
          nextValue = parseTags(value);
        }

        dispatch({
          type: 'draft.set',
          payload: {
            path: 'edits.' + field,
            value: nextValue,
          },
        });
      },
      delta({ dispatch, state }, args) {
        const sku = navParam(state);
        if (!sku) return;
        dispatch({
          type: 'inventory/updateQty',
          payload: {
            sku,
            delta: toNumber(asRecord(args).delta, 0),
          },
        });
      },
      save({ dispatch, state }) {
        const sku = navParam(state);
        if (!sku) return;
        dispatch({
          type: 'inventory/saveItem',
          payload: {
            sku,
            edits: asRecord(draft(state).edits),
          },
        });
        dispatch({ type: 'draft.patch', payload: { edits: {} } });
        dispatch({ type: 'notify.show', payload: { message: 'Saved ' + sku } });
      },
      remove({ dispatch, state }) {
        const sku = navParam(state);
        if (!sku) return;
        dispatch({ type: 'inventory/deleteItem', payload: { sku } });
        dispatch({ type: 'notify.show', payload: { message: 'Deleted ' + sku } });
        dispatch({ type: 'nav.back' });
      },
    },
  }),
  'ui.card.v1',
);

// @ts-check
__card__({
  id: 'lowStock',
  packId: 'ui.card.v1',
  title: 'Low Stock',
  icon: '⚠️',
});

__doc__({
  name: 'lowStock',
  summary: 'Threshold-based inventory triage view for low or empty stock.',
  tags: ['inventory', 'triage', 'alerts'],
  related: ['ui.table', 'itemDetail'],
});

doc`
---
symbol: lowStock
---
The lowStock card filters inventory rows against the active threshold and demonstrates a simple
alert-style workflow with mock supplier and print actions.
`;

defineRuntimeSurface(
  'lowStock',
  ({ ui }) => ({
    render({ state }) {
      const low = threshold(state);
      const items = selectItems(state).filter((item) => toNumber(asRecord(item).qty, 0) <= low);
      const quickOpen = items.slice(0, 10).map((item) => {
        const row = asRecord(item);
        const sku = String(row.sku || '');
        return ui.button('Open ' + sku, { onClick: { handler: 'open', args: { sku } } });
      });

      return ui.panel([
        ui.text('Low Stock (threshold ≤ ' + String(low) + ')'),
        ui.table(itemRows(items), { headers: ['SKU', 'Name', 'Category', 'Price', 'Qty'] }),
        items.length === 0 ? ui.badge('All stocked up') : ui.text('Quick open:'),
        ui.column(quickOpen),
        ui.row([
          ui.button('📧 Email Supplier', { onClick: { handler: 'notify', args: { message: 'Reorder email drafted (mock)' } } }),
          ui.button('🖨 Print', { onClick: { handler: 'notify', args: { message: 'Sent to printer (mock)' } } }),
        ]),
      ]);
    },
    handlers: {
      open({ dispatch }, args) {
        dispatch({
          type: 'nav.go',
          payload: {
            surfaceId: 'itemDetail',
            param: String(asRecord(args).sku || ''),
          },
        });
      },
      notify({ dispatch }, args) {
        dispatch({ type: 'notify.show', payload: { message: String(asRecord(args).message || '') } });
      },
    },
  }),
  'ui.card.v1',
);

// @ts-check
__card__({
  id: 'newItem',
  packId: 'ui.card.v1',
  title: 'New Item',
  icon: '➕',
});

__doc__({
  name: 'newItem',
  summary: 'Creation form for adding a new inventory item.',
  tags: ['inventory', 'create', 'forms'],
  related: ['ui.input', 'home'],
});

doc`
---
symbol: newItem
---
The newItem card demonstrates a full create flow with validation, draft state, and success
notifications using the ui.card.v1 primitives.
`;

defineRuntimeSurface(
  'newItem',
  ({ ui }) => ({
    render({ state }) {
      const draftState = draft(state);
      const form = asRecord(draftState.form);
      const submitResult = String(draftState.submitResult || '');
      return ui.panel([
        ui.text('Create New Item'),
        ui.row([
          ui.text('SKU:'),
          ui.input(String(form.sku || ''), { onChange: { handler: 'change', args: { field: 'sku' } } }),
        ]),
        ui.row([
          ui.text('Name:'),
          ui.input(String(form.name || ''), { onChange: { handler: 'change', args: { field: 'name' } } }),
        ]),
        ui.row([
          ui.text('Category:'),
          ui.input(String(form.category || ''), { onChange: { handler: 'change', args: { field: 'category' } } }),
        ]),
        ui.row([
          ui.text('Price:'),
          ui.input(String(toNumber(form.price, 0)), { onChange: { handler: 'change', args: { field: 'price' } } }),
        ]),
        ui.row([
          ui.text('Cost:'),
          ui.input(String(toNumber(form.cost, 0)), { onChange: { handler: 'change', args: { field: 'cost' } } }),
        ]),
        ui.row([
          ui.text('Qty:'),
          ui.input(String(toNumber(form.qty, 0)), { onChange: { handler: 'change', args: { field: 'qty' } } }),
        ]),
        submitResult ? ui.badge(submitResult) : ui.text(''),
        ui.row([
          ui.button('💾 Create Item', { onClick: { handler: 'submit' } }),
          ui.button('🏠 Home', { onClick: { handler: 'goHome' } }),
        ]),
      ]);
    },
    handlers: {
      change({ dispatch }, args) {
        const field = String(asRecord(args).field || '');
        if (!field) return;
        let value = asRecord(args).value;
        if (field === 'price' || field === 'cost' || field === 'qty') {
          value = toNumber(value, 0);
        }
        dispatch({
          type: 'draft.set',
          payload: {
            path: 'form.' + field,
            value,
          },
        });
      },
      submit({ dispatch, state }) {
        const form = asRecord(draft(state).form);
        const sku = String(form.sku || '').trim();
        const name = String(form.name || '').trim();
        if (!sku || !name) {
          dispatch({
            type: 'draft.set',
            payload: {
              path: 'submitResult',
              value: '❌ SKU and Name are required',
            },
          });
          return;
        }

        dispatch({
          type: 'inventory/createItem',
          payload: {
            sku,
            name,
            category: String(form.category || 'Accessories'),
            price: toNumber(form.price, 0),
            cost: toNumber(form.cost, 0),
            qty: toNumber(form.qty, 0),
            tags: [],
          },
        });

        dispatch({
          type: 'draft.patch',
          payload: {
            form: { sku: '', name: '', category: 'Accessories', price: 0, cost: 0, qty: 0 },
            submitResult: '✅ Created ' + sku,
          },
        });
        dispatch({ type: 'notify.show', payload: { message: 'Created ' + sku } });
      },
      goHome({ dispatch }) {
        dispatch({ type: 'nav.go', payload: { surfaceId: 'home' } });
      },
    },
  }),
  'ui.card.v1',
);

// @ts-check
__card__({
  id: 'priceCheck',
  packId: 'ui.card.v1',
  title: 'Price Checker',
  icon: '🏷',
});

__doc__({
  name: 'priceCheck',
  summary: 'Single-field lookup card for checking current price and stock.',
  tags: ['inventory', 'lookup', 'forms'],
  related: ['ui.input', 'ui.badge'],
});

doc`
---
symbol: priceCheck
---
The priceCheck card is the smallest form example in the inventory stack. It shows how a simple
lookup flow can still use the same draft/result pattern as larger cards.
`;

defineRuntimeSurface(
  'priceCheck',
  ({ ui }) => ({
    render({ state }) {
      const draftState = draft(state);
      const form = asRecord(draftState.form);
      const submitResult = String(draftState.submitResult || '');
      return ui.panel([
        ui.text('Price Checker'),
        ui.row([
          ui.text('SKU:'),
          ui.input(String(form.sku || ''), { onChange: { handler: 'change', args: { field: 'sku' } } }),
        ]),
        submitResult ? ui.badge(submitResult) : ui.text(''),
        ui.button('🔍 Look Up Price', { onClick: { handler: 'submit' } }),
      ]);
    },
    handlers: {
      change({ dispatch }, args) {
        dispatch({
          type: 'draft.set',
          payload: {
            path: 'form.sku',
            value: String(asRecord(args).value || ''),
          },
        });
      },
      submit({ dispatch, state }) {
        const sku = String(asRecord(draft(state).form).sku || '').trim();
        const item = findItem(state, sku);
        if (!item) {
          dispatch({
            type: 'draft.set',
            payload: {
              path: 'submitResult',
              value: '❌ SKU "' + sku + '" not found',
            },
          });
          return;
        }
        dispatch({
          type: 'draft.set',
          payload: {
            path: 'submitResult',
            value:
              '✅ ' +
              String(asRecord(item).name || '') +
              ' — ' +
              toMoney(asRecord(item).price) +
              ' (' +
              String(toNumber(asRecord(item).qty, 0)) +
              ' in stock)',
          },
        });
      },
    },
  }),
  'ui.card.v1',
);

// @ts-check
__card__({
  id: 'receive',
  packId: 'ui.card.v1',
  title: 'Receive Shipment',
  icon: '📦',
});

__doc__({
  name: 'receive',
  summary: 'Receiving workflow for adding stock back into inventory.',
  tags: ['inventory', 'receiving', 'forms'],
  related: ['ui.input', 'ui.badge'],
});

doc`
---
symbol: receive
---
The receive card is a compact form workflow for stock intake. It demonstrates draft-backed form
state and a simple success/error result badge.
`;

defineRuntimeSurface(
  'receive',
  ({ ui }) => ({
    render({ state }) {
      const draftState = draft(state);
      const form = asRecord(draftState.form);
      const submitResult = String(draftState.submitResult || '');
      return ui.panel([
        ui.text('Receive Shipment'),
        ui.row([
          ui.text('SKU:'),
          ui.input(String(form.sku || ''), { onChange: { handler: 'change', args: { field: 'sku' } } }),
        ]),
        ui.row([
          ui.text('Qty:'),
          ui.input(String(toNumber(form.qty, 1)), { onChange: { handler: 'change', args: { field: 'qty' } } }),
        ]),
        ui.row([
          ui.text('Note:'),
          ui.input(String(form.note || ''), { onChange: { handler: 'change', args: { field: 'note' } } }),
        ]),
        submitResult ? ui.badge(submitResult) : ui.text(''),
        ui.button('📦 Receive Stock', { onClick: { handler: 'submit' } }),
      ]);
    },
    handlers: {
      change({ dispatch }, args) {
        const field = String(asRecord(args).field || '');
        if (!field) return;
        let value = asRecord(args).value;
        if (field === 'qty') {
          value = toNumber(value, 0);
        }
        dispatch({
          type: 'draft.set',
          payload: {
            path: 'form.' + field,
            value,
          },
        });
      },
      submit({ dispatch, state }) {
        const form = asRecord(draft(state).form);
        const sku = String(form.sku || '').trim();
        const qty = toNumber(form.qty, 0);
        if (!sku || qty <= 0) {
          dispatch({
            type: 'draft.set',
            payload: {
              path: 'submitResult',
              value: '❌ SKU and qty are required',
            },
          });
          return;
        }

        dispatch({ type: 'inventory/receiveStock', payload: { sku, qty } });
        dispatch({
          type: 'draft.patch',
          payload: {
            form: { sku: '', qty: 1, note: '' },
            submitResult: '✅ Received +' + String(qty) + ' for ' + sku,
          },
        });
        dispatch({ type: 'notify.show', payload: { message: 'Received stock for ' + sku } });
      },
    },
  }),
  'ui.card.v1',
);

